import{_ as o,o as c,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"注解：","description":"","frontmatter":{"title":"注解：","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/04-Java 注解/注解：.md","filePath":"posts/java快速入门/第六部分：Spring 生态/04-Java 注解/注解：.md"}'),n={name:"posts/java快速入门/第六部分：Spring 生态/04-Java 注解/注解：.md"};function a(i,e,l,p,s,r){return c(),d("div",null,[...e[0]||(e[0]=[t("<div><p>概念：说明程序的。给计算机看的 注释：用文字描述程序的。给程序员看的</p><p><strong>定义：</strong> 注解（<code>Annotation</code>），也叫元数据。一种代码级别的说明。它是<code>JDK1.5</code>及以后版本引入的一个特性，与类、接口、枚举是在同一个层次。它可以声明在包、类、字段、方法、局部变量、方法参数等的前面，用来对这些元素进行说明，注释。</p><p><strong>概念描述：</strong><code>* JDK1.5</code>之后的新特性 <code>*</code> 说明程序的 <code>*</code> 使用注解：<code>@</code>注解名称</p><p>作用分类：</p><ol><li>编写文档：通过代码里标识的注解生成文档【生成文档<code>doc</code>文档】</li><li>代码分析：通过代码里标识的注解对代码进行分析【使用反射】</li><li>编译检查：通过代码里标识的注解让编译器能够实现基本的编译检查【<code>Override</code>】</li></ol><p><code>JDK</code>中预定义的一些注解</p><ul><li>@Override  ：检测被该注解标注的方法是否是继承自父类<code>(</code>接口<code>)</code>的 <code>* @Deprecated</code>：该注解标注的内容，表示已过时 <code>* @SuppressWarnings</code>：压制警告</li></ul><p><code>*</code></p><p>一般传递参数</p><p>all @SuppressWarnings(&quot;all&quot;)     <strong>自定义注解</strong>  <code>*</code> 格式：  元注解  <code>public @interface</code> 注解名称<code>{</code>        属性列表<code>;</code>  <code>}</code>  <code>*</code> 本质：注解本质上就是一个接口，该接口默认继承<code>Annotation</code>接口       <code>* public interface MyAnno extends java.lang.annotation.Annotation {}</code>  <code>*</code> 属性：接口中的抽象方法     要求： <code>1.</code> 属性的返回值类型有下列取值  <code>*</code> 基本数据类型  <code>* String</code>  <code>*</code> 枚举  <code>*</code> 注解  <code>*</code> 以上类型的数组 <code>2.</code> 定义了属性，在使用时需要给属性赋值</p><ul><li>如果定义属性时，使用<code>default</code>关键字给属性默认初始化值，则使用注解时，可以不进行属性的赋值。</li><li>如果只有一个属性需要赋值，并且属性的名称是<code>value</code>，则<code>value</code>可以省略，直接定义值即可。</li><li>数组赋值时，值使用<code>{}</code>包裹。如果数组中只有一个值，则<code>{}</code>可以省略</li></ul><p><strong>元注解：用于描述注解的注解</strong><code>@Target</code>：描述注解能够作用的位置       <code>* ElementType</code>取值：       <code>* TYPE</code>：可以作用于类上       <code>* METHOD</code>：可以作用于方法上    <code>* FIELD</code>：可以作用于成员变量上</p><p><code>@Retention</code>：描述注解被保留的阶段      <code>@Retention(RetentionPolicy.RUNTIME)</code>：当前被描述的注解，会保留到<code>class</code>字节码文件中，并被<code>JVM</code>读取到</p><p><code>@Documented</code>：描述注解是否被抽取到<code>api</code>文档中</p><p><code>@Inherited</code>：描述注解是否被子类继承</p><p><strong>在程序使用</strong><code>(</code><strong>解析</strong><code>)</code><strong>注解：获取注解中定义的属性值</strong>  <code>1.</code> 获取注解定义的位置的对象 （<code>Class</code>，<code>Method,Field</code>）  <code>2.</code> 获取指定的注解</p><ul><li>getAnnotation(Class) // 其实就是在内存中生成了一个该注解接口的子类实现对象 <code>public class ProImpl implements Pro{</code>      <code>public String className(){</code>          <code>return &quot;cn.itcast.annotation.Demo1&quot;;</code>     <code>}</code>     <code>public String methodName(){</code>          <code>return &quot;show&quot;;</code></li></ul><p>} } 3. 调用注解中的抽象方法获取配置的属性值</p><p>案例：简单的测试框架     <code>*</code> 小结：  <code>1.</code> 以后大多数时候，我们会使用注解，而不是自定义注解  <code>2.</code> 注解给谁用？</p><ul><li>编译器</li><li>给解析程序用</li></ul><p><code>3.</code> 注解不是程序的一部分，可以理解为注解就是一个标签</p></div>",1)])])}const _=o(n,[["render",a]]);export{g as __pageData,_ as default};
